import { posix as path } from 'node:path';
import { fileURLToPath } from 'node:url';
import { IverilogWasmError } from './errors.js';
const INTERNAL_ROOT = '/.iverilog';
const PREPROCESSED_PATH = `${INTERNAL_ROOT}/preprocessed.v`;
const FLAGS_PATH = `${INTERNAL_ROOT}/ivlpp.flags`;
const CONFIG_PATH = `${INTERNAL_ROOT}/ivl.conf`;
const PROGRAM_PATH = `${INTERNAL_ROOT}/program.vvp`;
function appendLine(target, text) {
    target.push(`${text}\n`);
}
async function createRuntime(name, output) {
    const loaderUrl = new URL(`./runtime/${name}.mjs`, import.meta.url);
    try {
        const module = await import(loaderUrl.href);
        return await module.default({
            locateFile(file) {
                return fileURLToPath(new URL(file, loaderUrl));
            },
            print(text) {
                appendLine(output.stdout, text);
                appendLine(output.combinedOutput, text);
            },
            printErr(text) {
                appendLine(output.stderr, text);
                appendLine(output.combinedOutput, text);
            },
        });
    }
    catch (cause) {
        const details = cause;
        if (details.code === 'ENOENT' && details.message.includes('.wasm')) {
            throw new IverilogWasmError('WASM_ASSET_MISSING', `Missing ${name} WebAssembly runtime asset.`, { cause });
        }
        throw new IverilogWasmError('RUNTIME_LOAD', `Failed to load the ${name} WebAssembly runtime.`, { cause });
    }
}
function writeFiles(runtime, files) {
    for (const file of files) {
        const destination = `/work/${file.path}`;
        runtime.FS.mkdirTree(path.dirname(destination));
        runtime.FS.writeFile(destination, typeof file.data === 'string'
            ? file.data
            : new Uint8Array(file.data));
    }
}
function setupWorkspace(runtime, files) {
    runtime.FS.mkdirTree('/work');
    runtime.FS.mkdirTree(INTERNAL_ROOT);
    writeFiles(runtime, files);
    runtime.FS.chdir('/work');
}
function changeRunDirectory(runtime, runCwd) {
    const destination = runCwd === '.' ? '/work' : `/work/${runCwd}`;
    const analyzed = runtime.FS.analyzePath(destination);
    if (!analyzed.exists || analyzed.object === null
        || !runtime.FS.isDir(analyzed.object.mode)) {
        throw new IverilogWasmError('INVALID_INPUT', `runCwd is not a staged virtual directory: ${runCwd}.`);
    }
    runtime.FS.chdir(destination);
}
function callMain(runtime, args) {
    const previousExitCode = process.exitCode;
    try {
        return runtime.callMain(args) ?? 0;
    }
    catch (error) {
        if (Number.isInteger(error?.status)) {
            return error.status;
        }
        throw error;
    }
    finally {
        process.exitCode = previousExitCode;
    }
}
async function executeStage(stage, runtimeName, files, prepare) {
    const started = performance.now();
    const output = { stdout: [], stderr: [], combinedOutput: [] };
    const runtime = await createRuntime(runtimeName, output);
    setupWorkspace(runtime, files);
    const exitCode = callMain(runtime, prepare(runtime));
    return {
        success: exitCode === 0,
        stage,
        exitCode,
        stdout: output.stdout.join(''),
        stderr: output.stderr.join(''),
        combinedOutput: output.combinedOutput.join(''),
        timings: { [stage]: performance.now() - started },
        runtime,
    };
}
function preprocessorFlags(request) {
    const records = ['D:__ICARUS__=1'];
    for (const [name, value] of Object.entries(request.defines)) {
        if (value === true)
            records.push(`D:${name}`);
        else if (value === false)
            records.push(`D:${name}=0`);
        else
            records.push(`D:${name}=${value}`);
    }
    for (const includeDir of request.includeDirs) {
        records.push(`I:${includeDir}`);
    }
    return `${records.join('\n')}\n`;
}
function compilerModules(generation) {
    const modules = ['system.vpi'];
    if (generation === '2005'
        || generation === '2009'
        || generation === '2012'
        || generation === '2017'
        || generation === '2023') {
        modules.push('v2005_math.vpi');
    }
    if (generation === '2005-sv'
        || generation === '2009'
        || generation === '2012'
        || generation === '2017'
        || generation === '2023') {
        modules.push('v2009.vpi');
    }
    return modules;
}
function compilerConfig(request) {
    return [
        'basedir:/work',
        ...compilerModules(request.generation).map(module => `module:${module}`),
        '-t:dll',
        'flag:DLL=vvp.tgt',
        `generation:${request.generation}`,
        `generation:${request.specify ? 'specify' : 'no-specify'}`,
        `out:${PROGRAM_PATH}`,
        'iwidth:32',
        'widthcap:65536',
        'functor:cprop',
        'functor:nodangle',
        ...(request.top === undefined ? [] : [`root:${request.top}`]),
        '',
    ].join('\n');
}
async function preprocess(request) {
    const execution = await executeStage('preprocess', 'ivlpp', request.files, runtime => {
        runtime.FS.writeFile(FLAGS_PATH, preprocessorFlags(request));
        return [
            '-F',
            FLAGS_PATH,
            '-L',
            '-o',
            PREPROCESSED_PATH,
            ...request.sources,
        ];
    });
    if (!execution.success)
        return execution;
    return {
        ...execution,
        preprocessed: new Uint8Array(execution.runtime.FS.readFile(PREPROCESSED_PATH)),
    };
}
async function compilePreprocessed(request, preprocessed) {
    const execution = await executeStage('compile', 'ivl', [], runtime => {
        runtime.FS.writeFile(PREPROCESSED_PATH, new Uint8Array(preprocessed));
        runtime.FS.writeFile(CONFIG_PATH, compilerConfig(request));
        return [`-C${CONFIG_PATH}`, '--', PREPROCESSED_PATH];
    });
    if (!execution.success)
        return execution;
    return {
        ...execution,
        program: new Uint8Array(execution.runtime.FS.readFile(PROGRAM_PATH)),
    };
}
async function executeProgram(request) {
    const execution = await executeStage('run', 'vvp', request.files, runtime => {
        runtime.FS.writeFile(PROGRAM_PATH, new Uint8Array(request.program));
        changeRunDirectory(runtime, request.runCwd);
        return [PROGRAM_PATH, ...request.plusargs];
    });
    const artifacts = new Map();
    for (const artifact of request.artifacts) {
        const artifactPath = `/work/${artifact}`;
        if (execution.runtime.FS.analyzePath(artifactPath).exists) {
            artifacts.set(artifact, new Uint8Array(execution.runtime.FS.readFile(artifactPath)));
        }
    }
    return {
        success: execution.success,
        stage: execution.stage,
        exitCode: execution.exitCode,
        stdout: execution.stdout,
        stderr: execution.stderr,
        combinedOutput: execution.combinedOutput,
        timings: execution.timings,
        artifacts,
    };
}
function stageResult(execution) {
    return {
        success: execution.success,
        stage: execution.stage,
        exitCode: execution.exitCode,
        stdout: execution.stdout,
        stderr: execution.stderr,
        combinedOutput: execution.combinedOutput,
        timings: execution.timings,
    };
}
export async function compileRuntime(request) {
    const preprocessed = await preprocess(request);
    if (!preprocessed.success || preprocessed.preprocessed === undefined) {
        return stageResult(preprocessed);
    }
    const compiled = await compilePreprocessed(request, preprocessed.preprocessed);
    return {
        ...stageResult(compiled),
        stdout: preprocessed.stdout + compiled.stdout,
        stderr: preprocessed.stderr + compiled.stderr,
        combinedOutput: preprocessed.combinedOutput + compiled.combinedOutput,
        timings: { ...preprocessed.timings, ...compiled.timings },
        ...(compiled.program === undefined ? {} : { program: compiled.program }),
    };
}
export async function runRuntime(request) {
    return executeProgram(request);
}
export async function simulateRuntime(request) {
    const compiled = await compileRuntime(request);
    if (!compiled.success || compiled.program === undefined) {
        return {
            ...compiled,
            artifacts: new Map(),
        };
    }
    const ran = await executeProgram({
        program: compiled.program,
        files: request.files,
        runCwd: request.runCwd,
        plusargs: request.plusargs,
        artifacts: request.artifacts,
        timeoutMs: request.timeoutMs,
    });
    return {
        ...ran,
        stdout: compiled.stdout + ran.stdout,
        stderr: compiled.stderr + ran.stderr,
        combinedOutput: compiled.combinedOutput + ran.combinedOutput,
        timings: { ...compiled.timings, ...ran.timings },
    };
}
